    const lock = rule.locked ? " 🔒" : "";
    const packages = packagesForRule(rule.code).join(", ") || "—";
    return `| ${rule.code}${lock} ([docs](${RULE_DOC_PATH}/${rule.code})) | \`${rule.slug}\` | ${rule.tier} | ${severityLabel(rule.defaultSeverity)} | ${packages} | ${rule.title} |`;
